/**
 * Where the trees, the rocks and the buildings of T2 and T3 stand (PLAN 2.8c, ADR-78): a scatter
 * seeded by the place. Pure and DOM-free; `GroundInstances` draws what it gives.
 *
 * **A nested lattice.** Level l has 2^l lattice points to a cell, and each point of a level is
 * a point of every finer level. An instance belongs to the coarsest level its point is on, and
 * stands near that point, moved by a hash of the point: so it stands at one place whatever the
 * zoom. A view shows the levels whose points are at least `SPACING_PX` apart on screen, and the
 * next finer one comes in by its opacity through the upper half of the octave of zoom before
 * its points are that far apart. Zooming in adds instances between those that are there and
 * moves none; nothing appears at once.
 *
 * **What stands at a point** is a matter of the ground there: buildings by how near a city is
 * and how large; else trees and rocks by the terrain class of the cell. Nothing stands on
 * water: by the cell's class and, where the fine mask is known, by its four pixels round the
 * place (PLAN 2.9b: where the drawn coast cannot be).
 *
 * **Its size** is a symbol's at T2, a few px that stand for "wood here" or "town here", and the
 * thing's own once the zoom shows it larger than that (a crown of 9 m is 9 px at 1 m/px).
 */
import { coastSure, type CoastMask } from '../../shared/landMask';
import { Terrain } from '../../shared/terrain';
import { hash2, pair } from '../hash';

export const ScatterKind = { Tree: 0, Rock: 1, Building: 2 } as const;

/** The least distance on screen between the lattice points of a level that is shown in full, CSS px. */
export const SPACING_PX = 14;
/** How far from its lattice point an instance may stand, as a share of its level's spacing. */
const JITTER = 0.35;
/** Floats to an instance: x and y from the view's centre (CSS px), size (CSS px), kind, opacity, variant (0–1). */
export const SCATTER_STRIDE = 6;

/** By terrain class: the chance that a lattice point has a tree, and a rock. */
const COVER: Record<number, { tree: number; rock: number }> = {
  [Terrain.Water]: { tree: 0, rock: 0 },
  [Terrain.Crossing]: { tree: 0, rock: 0 },
  [Terrain.Plains]: { tree: 0.05, rock: 0 },
  [Terrain.Grassland]: { tree: 0.04, rock: 0 },
  [Terrain.Forest]: { tree: 0.75, rock: 0 },
  [Terrain.Hills]: { tree: 0.12, rock: 0.1 },
  [Terrain.Mountains]: { tree: 0.08, rock: 0.42 },
  [Terrain.Desert]: { tree: 0, rock: 0.05 },
  [Terrain.Tundra]: { tree: 0.02, rock: 0.04 },
  [Terrain.Marsh]: { tree: 0.07, rock: 0 },
  [Terrain.Urban]: { tree: 0.04, rock: 0 },
  [Terrain.Ice]: { tree: 0, rock: 0 },
};

/** By kind: the size of its symbol (CSS px) and of the thing (m). */
const SIZE: Record<number, { px: number; m: number }> = {
  [ScatterKind.Tree]: { px: 7, m: 9 },
  [ScatterKind.Rock]: { px: 6, m: 5 },
  [ScatterKind.Building]: { px: 7, m: 14 },
};

/** How far a city's buildings reach, km, by its size (1 town … 5 metropolis). */
const CITY_REACH_KM = [0, 3, 5, 8, 12, 18];
/** The chance of a building at a city's very middle. */
const CITY_DENSITY = 0.85;

/** The cities, by the cells their buildings reach. */
export interface CityIndex {
  w: number;
  /** A looping map (PLAN 7.4f46): a city's reach goes over the seam, and its distance the short way round. */
  wrapX: boolean;
  x: Float64Array;
  y: Float64Array;
  /** Reach in cells. */
  reach: Float64Array;
  byCell: Map<number, number[]>;
}

export function cityIndex(cities: readonly { x: number; y: number; size: number }[], w: number, h: number, kmPerCell: number, wrapX = false): CityIndex {
  const idx: CityIndex = { w, wrapX, x: new Float64Array(cities.length), y: new Float64Array(cities.length), reach: new Float64Array(cities.length), byCell: new Map() };
  cities.forEach((c, k) => {
    const reach = CITY_REACH_KM[Math.max(0, Math.min(5, Math.round(c.size)))]! / kmPerCell;
    idx.x[k] = c.x;
    idx.y[k] = c.y;
    idx.reach[k] = reach;
    for (let cy = Math.max(0, Math.floor(c.y - reach)); cy <= Math.min(h - 1, Math.floor(c.y + reach)); cy++) {
      // On a looping map across the seam: a city by it had buildings to the seam and none beyond.
      for (let cx = wrapX ? Math.floor(c.x - reach) : Math.max(0, Math.floor(c.x - reach)); cx <= (wrapX ? Math.floor(c.x + reach) : Math.min(w - 1, Math.floor(c.x + reach))); cx++) {
        const key = cy * w + (((cx % w) + w) % w);
        const list = idx.byCell.get(key);
        if (list) list.push(k);
        else idx.byCell.set(key, [k]);
      }
    }
  });
  return idx;
}

/** The chance of a building at (`x`, `y`): most at a city's middle, none beyond its reach. */
export function cityDensity(idx: CityIndex, x: number, y: number): number {
  const list = idx.byCell.get(Math.floor(y) * idx.w + Math.floor(x));
  if (!list) return 0;
  let best = 0;
  for (const k of list) {
    let dx = x - idx.x[k]!;
    if (idx.wrapX) dx -= idx.w * Math.round(dx / idx.w);
    const d = Math.hypot(dx, y - idx.y[k]!) / idx.reach[k]!;
    if (d < 1) best = Math.max(best, CITY_DENSITY * (1 - d) ** 1.3);
  }
  return best;
}

export interface ScatterWorld {
  w: number;
  h: number;
  wrapX: boolean;
  kmPerCell: number;
  /** Terrain class of each cell. */
  terrain: Uint8Array;
  /** The fine land mask's coast, or null: the coast follows the cells. */
  mask: CoastMask | null;
  cities: CityIndex;
}

/** A view: its centre and half its size in cells, and CSS px to a cell. */
export interface ScatterView {
  cx: number;
  cy: number;
  halfW: number;
  halfH: number;
  pxPerCell: number;
}

export interface Scatter {
  count: number;
  /** `count` × SCATTER_STRIDE floats, the instances of the coarser levels first. */
  data: Float32Array;
  /** The finest level shown in full. */
  level: number;
  /** There were more than the cap. */
  truncated: boolean;
  /** Instances left out by the thinning (PLAN 7.1l6). */
  thinned: number;
}

/**
 * Instances a view of `vw` × `vh` CSS px can hold (PLAN 7.1l6): the most of a full view of
 * forest is 0.008 a px², at the zoom where a finer level begins to come in (16,569 at 1920 ×
 * 1080); a city's middle has a building at 0.85 of the points where a forest has a tree at
 * 0.75. With room to spare, so that no view is cut at a line. (It was 12,000 at any size: the
 * scatter filled it row by row, and below the row it reached the finer level stopped.)
 */
export function groundCap(vw: number, vh: number): number {
  return Math.ceil(vw * vh * 0.01) + 1000;
}

/** Where the thinning ranks each instance: a level's and its place's, and its key. */
let rankOf = new Uint16Array(0);
let keyOf = new Uint16Array(0);

/**
 * The instances of `view`, at most `cap`. `out` is reused when it is large enough. Past
 * `afford`, as many as a frame affords, they are thinned evenly (PLAN 7.1l6): the finest level
 * first, each of its instances kept by a hash of its place, so the ones left are spread across
 * the view as before, fewer; a coarser level only when the finer ones are gone. (A cut at the
 * cap left the view's top in full and nothing of the finer level below a line.)
 */
export function scatter(world: ScatterWorld, view: ScatterView, cap: number, out?: Float32Array, afford = cap): Scatter {
  const data = out && out.length >= cap * SCATTER_STRIDE ? out : new Float32Array(cap * SCATTER_STRIDE);
  if (afford < cap && rankOf.length < cap) {
    rankOf = new Uint16Array(cap);
    keyOf = new Uint16Array(cap);
  }
  const f = Math.log2(view.pxPerCell / SPACING_PX);
  // Below level 0 the levels go on, coarser: level −k is every 2^k-th point of level 0 each way
  // (PLAN 2.11l; until then a view further out than level 0 got every point of it, however
  // close on the screen).
  const level = Math.floor(f);
  // The next finer level, on its way in through the upper half of the octave.
  const t = Math.min(1, Math.max(0, (f - level - 0.5) / 0.5));
  const fade = t * t * (3 - 2 * t);
  /** In points of level 0: how far apart the points of the level shown in full are, and those looked at. */
  const coarse = level < 0 ? 2 ** -level : 1;
  const stride = level < 0 && fade > 0 ? coarse / 2 : coarse;
  const mPerPx = (world.kmPerCell * 1000) / view.pxPerCell;
  // A margin of a symbol's width: what stands just outside the view reaches into it.
  const margin = 16 / view.pxPerCell;
  const [x0, x1, y0, y1] = [view.cx - view.halfW - margin, view.cx + view.halfW + margin, view.cy - view.halfH - margin, view.cy + view.halfH + margin];
  let count = 0;
  let truncated = false;

  const finest = level < 0 ? 0 : level + (fade > 0 ? 1 : 0);
  for (let l = 0; l <= finest && !truncated; l++) {
    const n = 2 ** l; // lattice points to a cell
    const period = world.w * n;
    // (Of level 0, further out than it: only the points of the levels shown.)
    const step = l === 0 ? stride : 1;
    const [i0, i1] = [Math.ceil(Math.floor(x0 * n - JITTER) / step) * step, Math.ceil(x1 * n + JITTER)];
    const [j0, j1] = [Math.ceil(Math.max(0, Math.floor(y0 * n - JITTER)) / step) * step, Math.min(world.h * n, Math.ceil(y1 * n + JITTER))];
    for (let j = j0; j <= j1 && !truncated; j += step) {
      for (let i = i0; i <= i1; i += step) {
        // A point of a coarser level is that level's.
        if (l > 0 && (i & 1) === 0 && (j & 1) === 0) continue;
        // In full: the points of the level shown in full and of the coarser ones. The next finer level by its fade.
        const alpha = level < 0 ? (i % coarse === 0 && j % coarse === 0 ? 1 : fade) : l <= level ? 1 : fade;
        // (The same point either side of the seam of a looping map.)
        const iw = world.wrapX ? ((i % period) + period) % period : i;
        const h = hash2(hash2(iw, j), l);
        const [jx, jy] = pair(h);
        const x = (i + jx * JITTER) / n;
        const y = (j + jy * JITTER) / n;
        if (x < x0 || x > x1 || y < y0 || y > y1 || y < 0 || y >= world.h) continue;
        if (!world.wrapX && (x < 0 || x >= world.w)) continue;
        const cellX = world.wrapX ? ((Math.floor(x) % world.w) + world.w) % world.w : Math.floor(x);
        const cls = world.terrain[Math.floor(y) * world.w + cellX]!;
        if (cls === Terrain.Water || cls === Terrain.Crossing) continue;
        // What stands here: three numbers in [0, 1) from the point's hash.
        const h2 = hash2(h, 0x51ed);
        const r = (h2 & 0xffff) / 65536;
        const variant = (h2 >>> 16) / 65536;
        const cover = COVER[cls] ?? COVER[Terrain.Plains]!;
        let kind: number;
        const built = world.cities.byCell.size > 0 ? cityDensity(world.cities, world.wrapX ? cellX + (x - Math.floor(x)) : x, y) : 0;
        if (built > 0 && ((hash2(h, 0xb17d) & 0xffff) / 65536) < built) kind = ScatterKind.Building;
        else if (r < cover.tree) kind = ScatterKind.Tree;
        else if (r < cover.tree + cover.rock) kind = ScatterKind.Rock;
        else continue;
        // Surely land (PLAN 2.9b): in a land pixel of the fine mask, and land in the picture drawn from it.
        if (world.mask && !coastSure(world.mask, world.w, world.h, x, y, world.wrapX)) continue;
        if (count === cap) {
          truncated = true;
          break;
        }
        const size = SIZE[kind]!;
        const vary = 0.8 + 0.4 * variant;
        if (afford < cap) {
          // Finer, the sooner thinned: a level's own number, and a point coming in by its fade after those in full.
          rankOf[count] = (alpha < 1 ? 64 : 0) + l;
          keyOf[count] = hash2(h, 0x7417) & 0xffff;
        }
        const o = count * SCATTER_STRIDE;
        data[o] = (x - view.cx) * view.pxPerCell;
        data[o + 1] = (y - view.cy) * view.pxPerCell;
        data[o + 2] = Math.max(size.px, size.m / mPerPx) * vary;
        data[o + 3] = kind;
        data[o + 4] = alpha;
        data[o + 5] = variant;
        count++;
      }
    }
  }
  const kept = afford < count ? thin(data, count, afford) : count;
  return { count: kept, data, level, truncated, thinned: count - kept };
}

/**
 * Keeps `afford` of the `count` instances of `data`, in place, in their order: the finest rank
 * goes first, and of the rank that is kept in part, those of the least keys.
 */
function thin(data: Float32Array, count: number, afford: number): number {
  const byRank = new Map<number, number>();
  for (let i = 0; i < count; i++) byRank.set(rankOf[i]!, (byRank.get(rankOf[i]!) ?? 0) + 1);
  // The rank kept in part, and how many of it; the finer ranks go, the coarser stay.
  let over = count - afford;
  let part = -1;
  let need = 0;
  for (const r of [...byRank.keys()].sort((a, b) => b - a)) {
    const n = byRank.get(r)!;
    if (over >= n) {
      over -= n;
      continue;
    }
    part = r;
    need = n - over;
    break;
  }
  // Of that rank, the keys below `below` in full, and the first `atBelow` with the key `below`.
  const hist = new Uint32Array(65536);
  for (let i = 0; i < count; i++) if (rankOf[i] === part) hist[keyOf[i]!]!++;
  let below = 0;
  let under = 0;
  while (under + hist[below]! <= need) under += hist[below++]!;
  let atBelow = need - under;
  let k = 0;
  for (let i = 0; i < count; i++) {
    const r = rankOf[i]!;
    const keepIt = r < part || (r === part && (keyOf[i]! < below || (keyOf[i] === below && atBelow-- > 0)));
    if (!keepIt) continue;
    if (k !== i) data.copyWithin(k * SCATTER_STRIDE, i * SCATTER_STRIDE, (i + 1) * SCATTER_STRIDE);
    k++;
  }
  return k;
}
